pub struct ThreatAnnunciationType {
    /// The id of the Threat Alert log entry.
    #[serde(rename = "ThreatAlertId")]
    #[builder(setter(into))]
    pub threat_alert_id: AlertIdType,
    /// Information about the Threat Alert.
    #[serde(rename = "ThreatInfo")]
    pub threat_info: ThreatConditionInfoType,
    /// The audio tone to be applied to the Threat Alert.
    #[serde(rename = "NotifyingTone")]
    #[builder(setter(strip_option(fallback = notifying_tone_opt)))]
    pub notifying_tone: Option<AudioToneInfoType>,
    /// Time of the threat detection.
    #[serde(rename = "TimeOfDetection")]
    pub time_of_detection: crate::common::TimeType,
}

impl Encode for ThreatAnnunciationType {
    fn encode(&self, w: &mut Writer) {
        self.threat_alert_id.encode(w);
        self.threat_info.encode(w);
        self.notifying_tone.encode(w);
        self.time_of_detection.encode(w);
    }
}

impl Decode for ThreatAnnunciationType {
    fn decode(r: &mut Reader<'_>) -> Result<Self, WireError> {
        Ok(Self {
            threat_alert_id: Decode::decode(r)?,
            threat_info: Decode::decode(r)?,
            notifying_tone: Decode::decode(r)?,
            time_of_detection: Decode::decode(r)?,
        })
    }
}

