/// Marker type for the service side of `M_Alert`.
#[derive(Debug, Clone, Copy)]
pub enum ServiceRole {}

impl crate::Role for ServiceRole {
    type Incoming = ServiceMessage;
    type Outgoing = ClientMessage;
    const NAME: &'static str = "M_Alert::Service";

    fn vtable() -> &'static onboardapi_sys::obapi_vtable {
        // SAFETY: the vtable is an immutable static defined by the C++ shim.
        unsafe { &*(&raw const onboardapi_sys::obapi_Alert_service_vtable) }
    }
}

/// `M_Alert::Service`: receives [`ServiceMessage`], sends [`ClientMessage`].
pub type Service = crate::Endpoint<ServiceRole>;

/// Typed senders, one per outgoing operation. They encode straight from borrowed data.
impl crate::Endpoint<ServiceRole> {
    /// Report static settings of the Alert Service.
    pub fn report_alert_settings(&self, settings: &AlertSettingsType) -> crate::Result<()> {
        let mut w = Writer::default();
        settings.encode(&mut w);
        self.send_raw(0, w.as_bytes())
    }

    /// Report the status with current count of active alarms and threats.
    pub fn report_alert_status(&self, status: &AlertStatusType, is_removed: bool) -> crate::Result<()> {
        let mut w = Writer::default();
        status.encode(&mut w);
        is_removed.encode(&mut w);
        self.send_raw(1, w.as_bytes())
    }

    /// Report an Alarm raised as a result of an Alarm condition.
    /// This is the Log entry.
    pub fn report_alarm_log(&self, key_alarm_id: &str, alarm: &AlarmLogType, is_removed: bool) -> crate::Result<()> {
        let mut w = Writer::default();
        key_alarm_id.encode(&mut w);
        alarm.encode(&mut w);
        is_removed.encode(&mut w);
        self.send_raw(2, w.as_bytes())
    }

    /// Report an Annunciation for an Alarm.
    /// Current annunciation text and tone for a specific crew role.
    /// Note: Only one alarm will be announced per Crew Role at one time.
    pub fn report_alarm_annunciation(&self, key_crew_role: &str, annunciation: &AlarmAnnunciationType, is_removed: bool) -> crate::Result<()> {
        let mut w = Writer::default();
        key_crew_role.encode(&mut w);
        annunciation.encode(&mut w);
        is_removed.encode(&mut w);
        self.send_raw(3, w.as_bytes())
    }

    /// Report an Alert for a detected Threat.
    pub fn report_threat_log(&self, key_threat_id: &str, threat: &ThreatLogType, is_removed: bool) -> crate::Result<()> {
        let mut w = Writer::default();
        key_threat_id.encode(&mut w);
        threat.encode(&mut w);
        is_removed.encode(&mut w);
        self.send_raw(4, w.as_bytes())
    }

    /// Report an Annunciation for a Threat Alert.
    /// Current annunciation text and tone.
    /// Note: Only one threat will be announced at one time.
    pub fn report_threat_annunciation(&self, annunciation: &ThreatAnnunciationType, is_removed: bool) -> crate::Result<()> {
        let mut w = Writer::default();
        annunciation.encode(&mut w);
        is_removed.encode(&mut w);
        self.send_raw(5, w.as_bytes())
    }

}

